package com.masalewala.api.controller;
import com.masalewala.api.model.Models.*;import com.masalewala.api.repository.Repositories.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController{private final Products products;private final Orders orders;private final Payments payments;private final Users users;AdminController(Products p,Orders o,Payments pay,Users u){products=p;orders=o;payments=pay;users=u;}@GetMapping("/analytics") Object analytics(){return Map.of("sales",orders.findAll().stream().map(o->o.grandTotal==null?java.math.BigDecimal.ZERO:o.grandTotal).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add),"orders",orders.count(),"customers",users.count(),"inventoryAlerts",products.findAll().stream().filter(p->p.stock<20).count());}@PostMapping("/products") Product create(@RequestBody Product p){return products.save(p);}@PutMapping("/products/{id}") Product update(@PathVariable Long id,@RequestBody Product p){p.id=id;return products.save(p);}@DeleteMapping("/products/{id}") void delete(@PathVariable Long id){products.deleteById(id);}@PatchMapping("/payments/{id}/approve") Payment approve(@PathVariable Long id){var p=payments.findById(id).orElseThrow();p.status=PaymentStatus.APPROVED;p.order.status=OrderStatus.PAYMENT_VERIFIED;return payments.save(p);}@GetMapping("/reports/excel") Map<String,String> excel(){return Map.of("url","/exports/sales.xlsx");}@GetMapping("/reports/pdf") Map<String,String> pdf(){return Map.of("url","/exports/sales.pdf");}}
